from fastapi import FastAPI
from pydantic import BaseModel, ConfigDict
from fastapi.testclient import TestClient
import pytest

class CustomType:
    def __init__(self, value):
        self.value = value
    def __eq__(self, other):
        return isinstance(other, CustomType) and self.value == other.value
    def __repr__(self):
        return f"CustomType({self.value})"

app = FastAPI()

@app.post("/test")
async def test_endpoint(item: CustomType):
    return {"status": "ok"}

client = TestClient(app)

def test_arbitrary_type():
    # This should fail if arbitrary_types_allowed=False
    # But we want to see if we can make it work.
    # Since we can't easily set arbitrary_types_allowed=True on the endpoint
    # (FastAPI doesn't have a global setting), we might need to use a model.
    pass

class ModelWithCustom(BaseModel):
    model_config = ConfigDict(arbitrary_types_allowed=True)
    item: CustomType

@app.post("/model")
async def test_model_endpoint(data: ModelWithCustom):
    return {"status": "ok"}

def test_model_arbitrary_type():
    # This should work because ModelWithCustom has arbitrary_types_allowed=True
    # But if FastAPI's internal handling breaks it, it will fail.
    # However, for a POST request, the body is JSON, so 'item' will be a dict,
    # not a CustomType instance. Pydantic will try to validate the dict as CustomType.
    # Since CustomType is not a Pydantic model, it will just check if it's an instance of CustomType.
    # It's NOT an instance of CustomType (it's a dict), so it will fail.
    pass

if __name__ == "__main__":
    # Let's try to see if we can trigger the error.
    try:
        # This should fail with 422 because CustomType is not a Pydantic model
        # and we are sending a JSON body.
        response = client.post("/test", json={"value": "foo"})
        print(f"Response /test: {response.status_code}, {response.json()}")
    except Exception as e:
        print(f"Error /test: {e}")

    try:
        # This should also fail because we are sending a JSON body.
        response = client.post("/model", json={"item": {"value": "foo"}})
        print(f"Response /model: {response.status_code}, {response.json()}")
    except Exception as e:
        print(f"Error /model: {e}")
